import re

def extract_demo(text, n):
    pat=rf'Demo pair {n} input \((\d+)x(\d+)\):\n(.*?)\nDemo pair {n} output \((\d+)x(\d+)\):\n(.*?)(?=\n\nSame instance|\nWrong attempts|\Z)'
    m=re.search(pat,text,re.S)
    if not m: raise ValueError(f'no match {n}')
    ih,iw,ib,oh,ow,ob=m.groups()
    def matrix(block):
        return [[int(x) for x in line.split()] for line in block.strip().splitlines()]
    return matrix(ib), matrix(ob)
